  function showDates() {
    var keys = Object.keys(EVENTS).sort(function (a, b) {
      var pa = a.split('-').map(Number), pb = b.split('-').map(Number);
      return pa[0] - pb[0] || pa[1] - pb[1];
    });
    openIlm('Aham Tareekhein', 'اہم اسلامی تواریخ', keys.map(function (k) {
      var p = k.split('-').map(Number);
      var evs = EVENTS[k].map(function (e) { return e[0] + (e[1] ? ' <small class="ilm-src" style="display:inline">(' + e[1] + ')</small>' : ''); }).join('<br>');
      return item(evs, '', p[1] + ' ' + HMONTHS[p[0]]);
    }).join(''));
  }


